import { NodeState } from "../types";
import { type Node } from "reactflow";

export function getBorderColor(nodeState: NodeState): string {
  switch (nodeState) {
    case NodeState.Active:
      return "purple.fg";
    case NodeState.Passed:
      return "fg.muted";
    case NodeState.Upcoming:
      return "border.emphasized";
  }
}

export function findFocusNode(nodes: Node[], activeNodeId: string | null): Node | null {
  if (activeNodeId) {
    return nodes.find((node) => node.id === activeNodeId) ?? null;
  }
  return nodes.findLast((node) => node.selected) ?? null;
}
